function validate([nums]) {
  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => v < -2147483648 || v > 2147483647)) return 'Each value is between -2^31 and 2^31 - 1.';
  // 32 copies of one value already give more than 2^31 - 1 constant subsequences.
  const copies = new Map();
  for (const v of nums) copies.set(v, (copies.get(v) ?? 0) + 1);
  if (Math.max(...copies.values()) >= 32) return 'The answer must fit in 32 bits, so no value may appear 32 or more times.';
  return null;
}

