    for (let j = 0; j < k; j++) {
      let count = 1;
      for (let i = 0; i < j; i++) if (nums[j] - nums[i] === nums[k] - nums[j]) count += ways[i][j];
      ways[j][k] = count;
      total += count - 1;
    }
  }
