function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const LOW = -2147483648, HIGH = 2147483647;
  const clamp = v => Math.max(LOW, Math.min(HIGH, v));
  if (size === 'small') {
    const n = 1 + pick(12);
    const mode = pick(4);
    if (mode === 0) return [Array.from({ length: n }, () => pick(7) - 3)];
    if (mode === 1) return [Array.from({ length: n }, () => [LOW, HIGH, 0, -1, 1, LOW + 1, HIGH - 1][pick(7)])];
    if (mode === 2) {
      // A planted progression with noise around it.
      const start = pick(41) - 20, step = pick(9) - 4;
      return [Array.from({ length: n }, (_, i) => rand() < 0.7 ? start + step * i : pick(41) - 20)];
    }
    return [Array.from({ length: n }, () => pick(2 * HIGH + 2) + LOW)];
  }
  // Large: 1000 values from a moderate range, so the count stays far below 2^31 - 1.
  for (;;) {
    const span = 2000 + pick(1000000);
    const nums = Array.from({ length: 1000 }, () => pick(2 * span + 1) - span);
    // Plant a few long progressions, some with huge steps near the value limits.
    for (let p = 0; p < 4; p++) {
      const start = pick(1000), step = rand() < 0.5 ? pick(2000) - 1000 : pick(2 * HIGH + 2) + LOW;
      const first = pick(2 * span + 1) - span;
      for (let i = 0; i < 12 && start + i * 7 < 1000; i++) nums[start + i * 7] = clamp(first + step * i);
    }
    // Count to confirm the guarantee before returning.
    const dp = nums.map(() => new Map());
    let total = 0;
    for (let i = 0; i < nums.length; i++) for (let j = 0; j < i; j++) { const d = nums[i] - nums[j], c = dp[j].get(d) ?? 0; total += c; dp[i].set(d, (dp[i].get(d) ?? 0) + c + 1); }
    if (total <= HIGH) return [nums];
  }
}
